import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.BLL-IG04.js";const p=JSON.parse('{"title":"Explanation: architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function n(c,e,r,d,l,m){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="explanation-architecture" tabindex="-1">Explanation: architecture <a class="header-anchor" href="#explanation-architecture" aria-label="Permalink to &quot;Explanation: architecture&quot;">​</a></h1><p>mimus is the falsification half of the ecosystem: <em>&quot;every claim in your docs, comments, and memory — still true?&quot;</em> It exists because memory without doubt decays into confident confabulation.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>The org stack is <strong>tamias → engines → orchestration → surfaces</strong>. mimus is an <strong>engine</strong> — repo-local, deterministic at its core, with advisory AI tiers that can never gate. It consumes <code>kuda</code>&#39;s index (symbol claims, card audits, the graph pass&#39;s edges) and <code>sturn</code>&#39;s WAL where present; its findings feed CI gates, <code>pavo</code> surfaces, and <code>peregrin</code> campaigns. It is the designated doubter of every other engine&#39;s output.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sources ──► extract ──► classify ──► verify ──► emit</span></span>
<span class="line"><span>   │          │           │           │          │</span></span>
<span class="line"><span> docs/*.md  claims     kinds:     checkers:   human |</span></span>
<span class="line"><span> comments   +lines     path…      fs cmd      json</span></span>
<span class="line"><span> .kuda/                 behavior  symbol      exit 1</span></span>
<span class="line"><span> cards                            rules</span></span></code></pre></div><p><strong>Extract</strong> pulls claim candidates (backticked spans, code blocks, prose patterns) with source+line.</p><p><strong>Classify</strong> sorts them into the taxonomy — conservatively: a span that might be a command but isn&#39;t in the binary allowlist is <em>not</em> a command claim.</p><p><strong>Verify</strong> runs the mechanical checkers plus <code>rules/*.toml</code>.</p><p><strong>Emit</strong> reports violations — or exits 1 to gate CI.</p><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p><code>mimus-core</code> holds domain types only (<code>Claim</code>, <code>Violation</code>, <code>TrustScore</code>, config). Every concern is a trait crate + adapter crates:</p><ul><li><code>mimus-check</code> (the checker port) → <code>mimus-check-fs</code>, <code>mimus-check-cmd</code>, <code>mimus-check-symbol</code> (against kuda&#39;s index); <code>mimus-check-graph</code> (ADR-0002) runs a <em>set-level</em> pass: claims + code edges become <code>(subject, relation, object)</code> triples, bucketed by subject — contradictions and stale references at mechanical speed; a second port, not a <code>Checker</code> impl, since it compares claims to each other</li><li>claim sources: markdown today, comments/cards wired in config</li><li><code>mimus-rules</code> — conventions as <code>rules/*.toml</code> data</li><li><code>mimus-vcs</code>→<code>mimus-git</code>, <code>mimus-config</code> (port + scarab-config impl), <code>mimus-secret</code>→<code>mimus-keyring</code>/<code>mimus-dotenv</code></li></ul><p>A new checker = new adapter crate; a new convention = a new rule file.</p><h2 id="the-evidence-bar" tabindex="-1">The evidence bar <a class="header-anchor" href="#the-evidence-bar" aria-label="Permalink to &quot;The evidence bar&quot;">​</a></h2><p>A violation is claim + evidence + suggested fix. No evidence, no finding — false positives kill a critic faster than false negatives. The semantic tier can never gate CI: it reports, a human adjudicates. Style opinions are never emitted at all.</p><h2 id="position-in-the-ecosystem" tabindex="-1">Position in the ecosystem <a class="header-anchor" href="#position-in-the-ecosystem" aria-label="Permalink to &quot;Position in the ecosystem&quot;">​</a></h2><ul><li><code>kuda</code> builds the index; <code>mimus</code> doubts it — <code>audit</code> trust-scores cards against source via provenance hashes.</li><li><code>reconcile</code> (planned third tool) auto-fixes what mimus confirms: claims rewritten to match reality — it consumes the JSON violation contract, not the checkers.</li></ul><p>See <a href="./claims.html">claims &amp; tiers</a> for the taxonomy and why the two tiers can never merge.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>mimus owns <strong>verification</strong> — claim extraction, checkers, rules, violations. It does not own:</p><ul><li><strong>Memory</strong> — <code>kuda</code> builds and stores the index; mimus reads it (symbol checker, <code>audit</code>, graph edges) and never writes cards.</li><li><strong>Fixing</strong> — <code>reconcile</code> (planned) consumes mimus&#39;s JSON violation contract to auto-fix; mimus reports, never rewrites.</li><li><strong>Distribution</strong> — the <code>mimus</code> command ships as a tamias pack (<code>libraries/mimus</code>); tamias owns install/transport.</li><li><strong>Secrets</strong> — <code>mimus-secret</code> ports resolve credentials; values never enter findings or logs.</li><li><strong>Style</strong> — style opinions are never emitted at all; mimus checks truth, not taste.</li></ul>`,22)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
